1084	      .from('caixas').select('*').eq('restaurant_id', restaurantId)
1085	      .in('status', ['aberto', 'expirado']).maybeSingle();
1086	
1087	    if (!caixa) throw new NotFoundException('Nenhum caixa aberto');
1088	
1089	    const { data: pedidosAbertos } = await this.supabase.client
1090	      .from('orders').select('id, status, total')
1091	      .eq('caixa_id', caixa.id)
1092	      .in('status', this.STATUS_ABERTOS);
1093	
1094	    const { data: comandasAbertas } = await this.supabase.client
1095	      .from('orders')
1096	      .select('id, status, mesa_id, mesas(numero, nome)')
1097	      .eq('caixa_id', caixa.id)
1098	      .eq('canal', 'presencial')
