1101	    const { data: mesasAbertas } = await this.supabase.client
1102	      .from('mesas')
1103	      .select('id, numero, nome, status')
1104	      .eq('restaurant_id', restaurantId)
1105	      .neq('status', 'livre');
1106	
1107	    const temPendencias = (pedidosAbertos ?? []).length > 0 || (comandasAbertas ?? []).length > 0 || (mesasAbertas ?? []).length > 0;
1108	
1109	    if (temPendencias && !body?.permitir_pendencias) {
1110	      throw new ConflictException({
1111	        message: 'Existem pendências em aberto: feche os pedidos, comandas e mesas antes de fechar o caixa',
1112	        pedidos_abertos: pedidosAbertos?.length ?? 0,
1113	        pedidos: pedidosAbertos ?? [],
1114	        comandas_abertas: comandasAbertas?.length ?? 0,
1115	        comandas: comandasAbertas ?? [],
1116	        mesas_abertas: mesasAbertas?.length ?? 0,
1117	        mesas: mesasAbertas ?? [],
1118	      });
1119	    }
1120	
1121	    const { data: todosPedidos } = await this.supabase.client
1122	      .from('orders').select('id, total, status, payment_method, canal, created_at')
1123	      .or(`caixa_id.eq.${caixa.id},and(caixa_id.is.null,created_at.gte.${caixa.aberto_em})`);
1124	
1125	    const saidas = (caixa.saidas ?? []) as any[];
1126	    const entradas = (caixa.entradas ?? []) as any[];
1127	    const pagamentosPorComanda = await this.buscarPagamentosPorComanda(todosPedidos ?? []);
1128	    const resumo = this.calcularResumo(todosPedidos ?? [], saidas, caixa.valor_inicial, entradas, pagamentosPorComanda);
1129	    const fechado_em = new Date().toISOString();
1130	
1131	    // Conferência: operador informa quanto contou; sistema compara com espécie calculada
1132	    const dinheiro_contado = body?.dinheiro_contado ?? (resumo.especie_calculada ?? 0);
1133	    const diferenca = dinheiro_contado - (resumo.especie_calculada ?? 0);
1134	    const destinacao_fechamento = {
1135	      dinheiro_contado,
1136	      especie_calculada: resumo.especie_calculada,
1137	      diferenca,
1138	      por_pagamento: resumo.por_pagamento,
1139	      conferencia_aprovada: false,
1140	    };
1141	
1142	    await this.supabase.client.from('caixas')
1143	      .update({
1144	        status: 'fechado', fechado_em, resumo, destinacao_fechamento,
1145	        fechado_com_pendencias: temPendencias,
1146	        pendencias_fechamento: temPendencias
1147	          ? { pedidos: pedidosAbertos ?? [], comandas: comandasAbertas ?? [], mesas: mesasAbertas ?? [] }
1148	          : null,
1149	      })
1150	      .eq('id', caixa.id);
1151	
1152	    // Sem caixa aberto não há como aceitar pedidos/comandas — fecha o restaurante junto
1153	    await this.updateAparencia(restaurantId, { aberto: false });
1154	
1155	    // saldo_caixa = dinheiro contado (o que vai pro cofre para o próximo caixa)
1156	    await this.supabase.client.from('restaurants')
1157	      .update({ saldo_caixa: Math.max(0, dinheiro_contado) }).eq('id', restaurantId);
